import { readFile, writeFile } from 'node:fs/promises';
import { mdiLightbulbOutline, mdiThermostat, mdiSpeaker, mdiCreationOutline, mdiMinus, mdiPlus, mdiPlay, mdiPause, mdiSkipPrevious, mdiSkipNext, mdiPlayOutline, mdiCircleOutline } from '@mdi/js';

const icons = { 'mdi:lightbulb-outline': mdiLightbulbOutline, 'mdi:thermostat': mdiThermostat, 'mdi:speaker': mdiSpeaker, 'mdi:creation-outline': mdiCreationOutline, 'mdi:minus': mdiMinus, 'mdi:plus': mdiPlus, 'mdi:play': mdiPlay, 'mdi:pause': mdiPause, 'mdi:skip-previous': mdiSkipPrevious, 'mdi:skip-next': mdiSkipNext, 'mdi:play-outline': mdiPlayOutline, 'mdi:circle-outline': mdiCircleOutline };
const bundle = (await readFile('dist/still-cards.js', 'utf8')).replace(/\/\/# sourceMappingURL=.*$/m, '');
const html = `<!doctype html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Still cards preview</title><style>
:root{font-family:system-ui,sans-serif;--still-accent:#4c745d;--still-surface:#fff;--still-text:#28332e;--still-muted:#606a62;--still-subtle:#f1f4ee;--still-border-color:#e3e8df;--still-radius:22px;--still-on-accent:#fff;--preview-muted:#606a62;--preview-border:#e3e8df;--preview-control:#f1f4ee;--preview-text:#28332e}
:root[data-mode=dark]{color-scheme:dark;--still-accent:#a8c5ae;--still-surface:#242c26;--still-text:#e6ece3;--still-muted:#a5afa5;--still-subtle:#2c352e;--still-border-color:#354036;--still-on-accent:#1c2b20;--preview-muted:#a5afa5;--preview-border:#354036;--preview-control:#2c352e;--preview-text:#e6ece3}
*{box-sizing:border-box}body{margin:0;background:transparent;color:var(--preview-text)}button,select{font:inherit;color:inherit}button{cursor:pointer}button:focus-visible,select:focus-visible{outline:2px solid var(--still-accent);outline-offset:3px}.toolbar{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin-bottom:16px;padding:16px;background:var(--still-surface);border:1px solid var(--preview-border);border-radius:var(--radius,14px)}.mode{display:flex;gap:4px;background:var(--preview-control);padding:3px;border-radius:9px}.mode button{border:0;background:transparent;padding:9px 12px;border-radius:7px;font-size:12px;min-height:36px}.mode button[aria-pressed=true]{background:var(--still-accent);color:var(--still-on-accent)}.palette{display:flex;gap:9px;margin-left:auto}.palette button{width:28px;height:28px;border:0;border-radius:50%;background:var(--swatch);position:relative}.palette button[aria-pressed=true]:after{content:'';position:absolute;inset:-3px;border:1px solid var(--swatch);border-radius:50%}.finish{display:flex;align-items:center;gap:7px;font-size:11px;color:var(--preview-muted)}select{background:var(--preview-control);border:1px solid var(--preview-border);border-radius:7px;padding:8px;font-size:12px;min-height:36px}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;align-items:start}still-card{height:auto}.note{font-size:11px;line-height:1.6;color:var(--muted-foreground,#606a62);margin:14px 0 0}.note span{color:inherit}@media(max-width:480px){.cards{grid-template-columns:minmax(0,1fr)}.toolbar{gap:14px}.finish{width:100%}.palette{margin-left:auto}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{transition:none!important}}
</style></head><body>
<div class="toolbar"><div class="mode" role="group" aria-label="Appearance"><button data-mode="light" aria-pressed="true">Daylight</button><button data-mode="dark" aria-pressed="false">After dark</button></div><div class="palette" role="group" aria-label="Accent"><button data-accent="0" aria-label="Sage accent" aria-pressed="true" style="--swatch:#4c745d"></button><button data-accent="1" aria-label="Clay accent" aria-pressed="false" style="--swatch:#996956"></button><button data-accent="2" aria-label="Ocean accent" aria-pressed="false" style="--swatch:#4a6f91"></button></div><label class="finish">Finish <select id="finish"><option value="soft">Soft</option><option value="outlined">Outline</option><option value="minimal">Minimal</option></select></label></div>
<div class="cards" id="cards"></div><p class="note" id="feedback" role="status">Interactive preview <span>·</span> Sample devices. Try a control or change the style.</p>
<script type="module">${bundle}</script>
<script type="module">
await customElements.whenDefined('still-card');
const paths=${JSON.stringify(icons)};
class PreviewIcon extends HTMLElement{set icon(value){this._icon=value;this.draw()}get icon(){return this._icon}connectedCallback(){this.draw()}draw(){this.innerHTML='<svg viewBox="0 0 24 24" width="100%" height="100%" fill="currentColor" aria-hidden="true"><path d="'+(paths[this._icon]||paths['mdi:circle-outline'])+'"></path></svg>'}}
if(!customElements.get('ha-icon'))customElements.define('ha-icon',PreviewIcon);
const state=(entity_id,state,friendly_name,attributes={})=>({entity_id,state,attributes:{friendly_name,...attributes}});
const list=[state('light.reading','on','Reading light',{brightness:166,supported_color_modes:['brightness']}),state('climate.living','heat','Just the right temperature',{temperature:22,current_temperature:21.5,min_temp:7,max_temp:35,target_temp_step:.5,supported_features:1,hvac_modes:['off','heat','cool']}),state('media_player.living','playing','A little background music',{media_title:'Evening, slowly',media_artist:'Still Sessions · Ambient',volume_level:.35,supported_features:16437}),state('scene.evening','ready','Slow evening')];
const configs=[{type:'custom:still-light-card',entity:'light.reading'},{type:'custom:still-climate-card',entity:'climate.living'},{type:'custom:still-media-card',entity:'media_player.living'},{type:'custom:still-scene-card',entity:'scene.evening',subtitle:'Dim the lights. Take a breath.'}];
const cards=[];let mode='light',accent=0;
let hass={states:Object.fromEntries(list.map(e=>[e.entity_id,e])),config:{unit_system:{temperature:'°C'}},callService:async(domain,service,data)=>{const old=hass.states[data.entity_id];const entity={...old,attributes:{...old.attributes}};if(service==='toggle')entity.state=entity.state==='on'?'off':'on';if(service==='turn_on')entity.state='on';if(service==='turn_off')entity.state='off';if(data.brightness_pct!==undefined)entity.attributes.brightness=data.brightness_pct/100*255;if(service==='set_temperature')entity.attributes.temperature=data.temperature;if(service==='set_hvac_mode')entity.state=data.hvac_mode;if(service==='media_pause')entity.state='paused';if(service==='media_play')entity.state='playing';if(service==='volume_set')entity.attributes.volume_level=data.volume_level;if(service==='media_next_track')entity.attributes.media_title='Sunday, slowly';if(service==='media_previous_track')entity.attributes.media_title='Evening, slowly';hass={...hass,states:{...hass.states,[entity.entity_id]:entity}};if(domain==='scene'){hass.states['light.reading']={...hass.states['light.reading'],state:'on',attributes:{...hass.states['light.reading'].attributes,brightness:60}};hass.states['media_player.living']={...hass.states['media_player.living'],state:'paused'}}cards.forEach(card=>card.hass=hass);document.querySelector('#feedback').textContent=domain==='scene'?'A slower evening. Lights dimmed, music paused.':'Updated · '+old.attributes.friendly_name;}};
configs.forEach(config=>{const card=document.createElement('still-card');card.setConfig(config);card.hass=hass;cards.push(card);document.querySelector('#cards').append(card)});
document.addEventListener('hass-more-info',event=>{const entity=hass.states[event.detail.entityId];document.querySelector('#feedback').textContent=entity.attributes.friendly_name+' · '+entity.state+' (sample device)'});
const colors=[['#4c745d','#a8c5ae'],['#996956','#d9ad95'],['#4a6f91','#a0bbd9']];
const applyAccent=()=>document.documentElement.style.setProperty('--still-accent',colors[accent][mode==='dark'?1:0]);
document.querySelectorAll('.mode button').forEach(button=>button.addEventListener('click',()=>{mode=button.dataset.mode;document.documentElement.dataset.mode=mode;document.querySelectorAll('.mode button').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));applyAccent()}));
document.querySelectorAll('[data-accent]').forEach(button=>button.addEventListener('click',()=>{accent=Number(button.dataset.accent);document.querySelectorAll('[data-accent]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));applyAccent()}));
document.querySelector('#finish').addEventListener('change',event=>{cards.forEach((card,index)=>card.setConfig({...configs[index],variant:event.target.value}))});
await Promise.all(cards.map(card=>card.updateComplete));
console.log('Still preview ready: four production cards.');
</script></body></html>`;
await writeFile('docs/preview.html', html);
console.log('Self-contained interactive preview saved to docs/preview.html.');
